  1	const { test } = require('node:test');
  2	const assert = require('node:assert/strict');
  3	const { readingTimeMinutes } = require('../src/textstats');
  4	
  5	// n copies of a one-word token, so the word count is exactly n.
  6	const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  7	
  8	// The same passage as test/wordCount.test.js; wc -w gives 64 words.
  9	const PASSAGE = [
 10	  'The lighthouse keeper climbed the spiral stairs every evening, counting',
 11	  'each step as his father had taught him. There were one hundred and twelve,',
 12	  'and on stormy nights the number never seemed to change, though his legs',
 13	  'insisted otherwise. At the top he trimmed the wick, polished the great lens,',
 14	  'and watched the beam sweep across the water toward ships he would never meet.',
 15	].join('\n');
 16	
 17	const CASES = [
 18	  ["", null, 0],
 19	  ["x", null, 1],
 20	  ["x x", null, 1],
 21	  ["", 50, 0],
 22	  ["x", 1, 1],
 23	  ["x x", 1, 2],
 24	  ["x x x", 1, 3],
 25	  ["x x x", 2, 2],
 60	});
 61	
 62	test('matches every row of the reference table', () => {
 63	  for (const [text, wpm, expected] of CASES) {
 64	    const actual = wpm === null ? readingTimeMinutes(text) : readingTimeMinutes(text, wpm);
 65	    assert.equal(actual, expected, JSON.stringify([text, wpm]));
 66	  }
 67	});
 68	
 69	test('throws a RangeError naming the function for an invalid wpm', () => {
 70	  const bad = [0, -0, -1, -200, NaN, Infinity, -Infinity, '200', '', null, true, {}, [], [200], 200n];
 71	  for (const wpm of bad) {
 72	    assert.throws(() => readingTimeMinutes('a b c', wpm), (err) => {
 73	      assert.ok(err instanceof RangeError, String(wpm));
 74	      assert.ok(err.message.startsWith('readingTimeMinutes:'), String(wpm));
 75	      return true;
 76	    });
 77	  }
 78	});
 79	
 80	test('rejects an invalid wpm even when the text is empty', () => {
 81	  assert.throws(() => readingTimeMinutes('', 0), RangeError);
 82	});
 83	
 84	test('defaults wpm to 200 when omitted or undefined', () => {
 85	  assert.equal(readingTimeMinutes(words(200)), 1);
 86	  assert.equal(readingTimeMinutes(words(200), undefined), 1);
 87	  assert.equal(readingTimeMinutes(words(201), undefined), 2);
 88	});
 89	
 90	test('accepts a fractional wpm and rounds up', () => {
 91	  // 301 / 150.5 = 2 exactly; 302 / 150.5 is just over 2, so it rounds up to 3.
 92	  assert.equal(readingTimeMinutes(words(301), 150.5), 2);
 93	  assert.equal(readingTimeMinutes(words(302), 150.5), 3);
 94	  // 1 / 0.5 = 2.
 95	  assert.equal(readingTimeMinutes('hello', 0.5), 2);
 96	});
 97	
 98	test('checks the text before the rate', () => {
 99	  for (const wpm of [0, -1, NaN, '200', null]) {
100	    assert.throws(() => readingTimeMinutes(42, wpm), (err) => {
101	      assert.ok(err instanceof TypeError);
102	      assert.ok(err.message.startsWith('readingTimeMinutes:'));
103	      return true;
104	    });
105	  }
106	});
107	
108	test('counts words the way wordCount does', () => {
109	  // Hyphenated compound and contractions: 1 word each.
110	  assert.equal(readingTimeMinutes('well-known don\'t keeper’s', 1), 3);
111	  // Decimals and domains split at the point: 3.14 is 2 words, example.com is 2.
112	  assert.equal(readingTimeMinutes('3.14', 1), 2);
113	  assert.equal(readingTimeMinutes('example.com', 1), 2);
114	  // Dashes and slashes separate: one, two, and, or = 4 words.
115	  assert.equal(readingTimeMinutes('one—two and/or', 1), 4);
116	});
117	
118	test('rounds three paragraphs of 270 words up to 2 minutes', () => {
119	  // Nine words per sentence, ten sentences per paragraph, three paragraphs.
120	  const sentence = 'The quick brown fox jumps over the lazy dog.';
121	  const paragraph = Array.from({ length: 10 }, () => sentence).join(' ');
122	  const text = [paragraph, paragraph, paragraph].join('\n\n');
123	  assert.equal(readingTimeMinutes(text), 2); // ceil(270 / 200) = ceil(1.35)
124	  assert.equal(readingTimeMinutes(text, 270), 1);
125	  assert.equal(readingTimeMinutes(text, 269), 2);
126	});
127	
128	test('rounds the 64-word passage up to 1 minute, or 7 at 10 wpm', () => {
129	  assert.equal(readingTimeMinutes(PASSAGE), 1); // ceil(64 / 200)
130	  assert.equal(readingTimeMinutes(PASSAGE, 10), 7); // ceil(6.4)
131	  assert.equal(readingTimeMinutes(PASSAGE, 64), 1);
132	  assert.equal(readingTimeMinutes(PASSAGE, 63), 2);
133	});

