111	  // Decimals and domains split at the point: 3.14 is 2 words, example.com is 2.
112	  assert.equal(readingTimeMinutes('3.14', 1), 2);
113	  assert.equal(readingTimeMinutes('example.com', 1), 2);
114	  // Dashes and slashes separate: one, two, and, or = 4 words.
115	  assert.equal(readingTimeMinutes('one—two and/or', 1), 4);
116	});
117	
118	test('rounds three paragraphs of 270 words up to 2 minutes', () => {
119	  // Nine words per sentence, ten sentences per paragraph, three paragraphs.
120	  const sentence = 'The quick brown fox jumps over the lazy dog.';
121	  const paragraph = Array.from({ length: 10 }, () => sentence).join(' ');
122	  const text = [paragraph, paragraph, paragraph].join('\n\n');
123	  assert.equal(readingTimeMinutes(text), 2); // ceil(270 / 200) = ceil(1.35)
124	  assert.equal(readingTimeMinutes(text, 270), 1);
125	  assert.equal(readingTimeMinutes(text, 269), 2);
126	});
127	
128	test('rounds the 64-word passage up to 1 minute, or 7 at 10 wpm', () => {
129	  assert.equal(readingTimeMinutes(PASSAGE), 1); // ceil(64 / 200)
130	  assert.equal(readingTimeMinutes(PASSAGE, 10), 7); // ceil(6.4)
131	  assert.equal(readingTimeMinutes(PASSAGE, 64), 1);
132	  assert.equal(readingTimeMinutes(PASSAGE, 63), 2);
133	});

